"""Back-test verdict shipped with the app (generated by evals/backtest.py into app/data/backtest.json)."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import Any

DATA = Path(__file__).parent / "data" / "backtest.json"


@lru_cache
def backtest() -> dict[str, Any]:
    try:
        return json.loads(DATA.read_text())
    except (OSError, ValueError):
        return {}


def note() -> tuple[bool, str]:
    s = backtest().get("summary")
    if not s:
        return False, "Not back-tested: probabilities are descriptive base rates, not validated forecasts."
    d, z, v = s["direction"], s["size"], s["verdict"]
    dir_txt = (
        f"direction calls beat the baselines (Brier {d['brier_model']} vs pooled {d['brier_pooled']})"
        if v["direction_validated"]
        else f"up/down probabilities did not beat a coin flip (Brier {d['brier_model']} vs {d['brier_coin']}); "
        "treat them as descriptive history, not a prediction"
    )
    size_txt = (
        f"expected move size beat the pooled baseline (error {z['mae_model']} vs {z['mae_pooled']} pp)"
        if v["size_validated"]
        else "expected move size did not beat the pooled baseline"
    )
    return bool(v["direction_validated"]), (
        f"Back-test ({s['n']} prints, {s['tickers']} large caps, {s['period'][0]} to {s['period'][1]}, no look-ahead): "
        f"{dir_txt}; {size_txt}."
    )


def load_predictions() -> int:
    """Insert back-test forecasts (source=backtest) once, so the track record shows calibration."""
    from datetime import date

    from app.db import Prediction, session_scope

    rows = backtest().get("rows") or []
    n = 0
    with session_scope() as s:
        if s.query(Prediction).filter(Prediction.source == "backtest").first():
            return 0
        for r in rows:
            s.add(
                Prediction(
                    id=f"bt:{r['ticker']}:{r['event_date']}",
                    ticker=r["ticker"],
                    event_date=date.fromisoformat(r["event_date"]),
                    kind="p_up_day1",
                    value=r["p_up"],
                    baseline=r["pooled_up"],
                    method="base_rate",
                    source="backtest",
                    outcome=r["up"],
                )
            )
            n += 1
    return n
